{
  "findings": [
    {
      "check_id": "CKV_AZURE_52",
      "title": "Minimum TLS version is not enforced",
      "resource": "azurerm_mssql_server.changeme_simple_mssql_server",
      "severity": "MEDIUM",
      "explanation": "The server does not specify minimum_tls_version, so clients may be permitted to negotiate obsolete TLS versions instead of requiring TLS 1.2."
    },
    {
      "check_id": "CKV_AZURE_113",
      "title": "Public network access is enabled",
      "resource": "azurerm_mssql_server.changeme_simple_mssql_server",
      "severity": "MEDIUM",
      "explanation": "Public network access defaults to enabled, exposing the SQL server's public endpoint to network-based attacks."
    },
    {
      "check_id": "CKV2_AZURE_27",
      "title": "Azure AD authentication is not configured",
      "resource": "azurerm_mssql_server.changeme_simple_mssql_server",
      "severity": "MEDIUM",
      "explanation": "The server has no Azure AD administrator, preventing centralized identity-based authentication and leaving only SQL credentials configured."
    },
    {
      "check_id": "CKV2_AZURE_45",
      "title": "Private endpoint is not configured",
      "resource": "azurerm_mssql_server.changeme_simple_mssql_server",
      "severity": "MEDIUM",
      "explanation": "No private endpoint connects this SQL server to a private subnet, so private network access is unavailable."
    },
    {
      "check_id": "CKV2_AZURE_2",
      "title": "SQL vulnerability assessment is disabled",
      "resource": "azurerm_mssql_server.changeme_simple_mssql_server",
      "severity": "MEDIUM",
      "explanation": "The server has no vulnerability assessment configuration, so recurring scans cannot identify database security weaknesses and configuration drift."
    },
    {
      "check_id": "CKV_AZURE_23",
      "title": "SQL auditing is not enabled",
      "resource": "azurerm_mssql_server.changeme_simple_mssql_server",
      "severity": "MEDIUM",
      "explanation": "No extended auditing policy is attached to the server, reducing visibility into database access and security-relevant activity."
    },
    {
      "check_id": "CKV_AZURE_24",
      "title": "SQL audit retention is not configured",
      "resource": "azurerm_mssql_server.changeme_simple_mssql_server",
      "severity": "MEDIUM",
      "explanation": "Because no auditing policy exists, audit records are not configured for retention greater than 90 days."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Hardcoded SQL administrator password",
      "resource": "azurerm_mssql_server.changeme_simple_mssql_server",
      "severity": "HIGH",
      "explanation": "The SQL administrator password is embedded directly in Terraform source, exposing it to source-control history and anyone who can read the configuration."
    }
  ],
  "patched_code": "variable \"mssql_administrator_login_password\" {\n  type      = string\n  sensitive = true\n}\n\nvariable \"mssql_azuread_admin_login_username\" {\n  type = string\n}\n\nvariable \"mssql_azuread_admin_object_id\" {\n  type = string\n}\n\nvariable \"mssql_azuread_tenant_id\" {\n  type = string\n}\n\nvariable \"mssql_private_endpoint_subnet_id\" {\n  type = string\n}\n\nvariable \"mssql_security_storage_endpoint\" {\n  type = string\n}\n
